// render.mjs — turns the extracted documentation model into markdown.
//
// The markdown is the primary artifact: it is committed to the repo (readable
// in a PR diff and on GitHub) and the static docs site is generated from these
// exact files, so the two can never disagree.

import { dedent, mdCell, mdCode, slugify } from './text.mjs';

const GENERATED_NOTICE =
  '<!-- Generated by `npm run docs:build` from component source and JSDoc. Do not edit by hand: edit the component or `scripts/docs/registry.mjs`. -->';

// ─────────────────────────────────────────────────────────────────────────────
// JSDoc prose → markdown
// ─────────────────────────────────────────────────────────────────────────────

/** `{@link Card}` → `` `Card` ``, `{@link Card|the card}` → `` `the card` ``. */
function normaliseJsDocLinks(text) {
  return text
    .replace(/\{@link\s+([^}|\s]+)(?:\|([^}]+))?\}/g, (_match, target, label) =>
      label ? `\`${label}\`` : `\`${target}\``,
    )
    .replace(/\{@(?:code|literal)\s+([^}]+)\}/g, (_match, value) => `\`${value}\``);
}

/**
 * Converts the loose indentation JSDoc uses for code samples into fenced
 * blocks, so `Usage:` followed by indented JSX renders as code:
 *
 *     Usage:
 *       <DataTable … />
 */
function indentedCodeToFence(text) {
  const lines = text.split('\n');
  const out = [];
  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i];
    const introducer = /^(\s*)(Usage|Example|Examples|E\.g\.|For example):\s*$/.exec(line);
    if (!introducer) {
      out.push(line);
      continue;
    }
    const body = [];
    while (i + 1 < lines.length && (lines[i + 1].trim() === '' || /^\s{2,}\S/.test(lines[i + 1]))) {
      body.push(lines[i + 1]);
      i += 1;
    }
    out.push(`${introducer[1]}${introducer[2]}:`, '', '```tsx');
    out.push(...dedent(body.join('\n')).split('\n'));
    out.push('```');
  }
  return out.join('\n');
}

export function normaliseProse(text) {
  if (!text) return '';
  return indentedCodeToFence(normaliseJsDocLinks(dedent(text)));
}

// ─────────────────────────────────────────────────────────────────────────────
// Building blocks
// ─────────────────────────────────────────────────────────────────────────────

function heading(level, text) {
  return `${'#'.repeat(level)} ${text}`;
}

function codeBlock(code, language = 'tsx') {
  return ['```' + language, dedent(code.replace(/\s+$/, '')), '```'].join('\n');
}

function propsTable(rows) {
  const header = ['| Prop | Type | Default | Required | Description |', '| --- | --- | --- | --- | --- |'];
  const body = rows.map((row) => {
    const required = row.kind === 'rest' ? '—' : row.optional ? 'No' : 'Yes';
    return `| ${[
      mdCell(mdCode(row.name)),
      mdCell(mdCode(row.type)),
      mdCell(row.hasDefault ? mdCode(row.defaultValue) : '—'),
      required,
      mdCell(row.description) || '—',
    ].join(' | ')} |`;
  });
  return [...header, ...body].join('\n');
}

function typeBlock(type, level) {
  const sections = [heading(level, `\`${type.name}\``)];
  if (type.description) sections.push('', normaliseProse(type.description));
  if (type.values?.length) {
    sections.push('', 'Allowed values:', '');
    sections.push(...type.values.map((value) => `- ${mdCode(value)}`));
  } else if (type.members?.length) {
    sections.push('', propsTable(type.members));
  } else if (type.typeText) {
    sections.push('', codeBlock(type.typeText, 'ts'));
  }
  return sections.join('\n');
}

function firstSentence(text) {
  if (!text) return '';
  const flat = text.replace(/\s+/g, ' ').trim();
  const match = /^(.{0,120}?[.!?])(\s|$)/.exec(flat);
  return match ? match[1] : flat.slice(0, 120);
}

// ─────────────────────────────────────────────────────────────────────────────
// Component page
// ─────────────────────────────────────────────────────────────────────────────

/** Stable, collision-free anchor for a component section on a compound page. */
function componentAnchor(component) {
  return `component-${slugify(component.name)}`;
}

function renderComponentSection(component, ctx) {
  // A page documenting one component uses `##` sections directly under the
  // title; a compound page (Card, live regions) nests them under `## <Name>`.
  const base = ctx.singleExport ? 2 : 3;
  const lines = [];

  if (!ctx.singleExport) {
    lines.push(`<a id="${componentAnchor(component)}"></a>`, '', heading(2, `\`${component.name}\``), '');
  }

  const meta = [`**Status:** ${component.deprecated ? 'deprecated' : 'stable'}`];
  if (component.since) meta.push(`**Since:** ${component.since}`);
  meta.push(`**Source:** \`${component.file}:${component.line}\``);
  lines.push(meta.join(' · '), '');

  if (component.deprecated) {
    // One blockquote, so the banner stays visually attached to its replacement
    // link on GitHub and on the docs site.
    const quoted = normaliseProse(component.deprecated)
      .split('\n')
      .map((line) => (line.trim() ? `> ${line}` : '>'));
    quoted[0] = `> ⚠️ **Deprecated.** ${quoted[0]?.slice(2) ?? ''}`.trimEnd();
    quoted.push('>');
    quoted.push(
      ctx.migrationTarget
        ? `> Migrate to [\`${ctx.migrationTarget.title}\`](./${ctx.migrationTarget.slug}.md).`
        : '> See the [migration guide](./migrations.md).',
    );
    lines.push(quoted.join('\n'), '');
  }

  if (component.description) lines.push(normaliseProse(component.description), '');

  lines.push(
    heading(base, 'Import'),
    '',
    codeBlock(`import { ${component.name} } from '@/${component.file.replace(/\.tsx?$/, '')}';`),
    '',
  );

  lines.push(heading(base, 'Props'), '');
  if (component.props.length) {
    lines.push(propsTable(component.props), '');
  } else {
    lines.push(
      `\`${component.name}\` declares no props of its own: every prop is forwarded to the underlying \`<${component.element ?? 'div'}>\` element.`,
      '',
    );
  }
  if (component.inheritedFrom.length || component.restMember) {
    lines.push(heading(base + 1, 'Inherited attributes'), '');
    const element = component.element ?? 'element';
    if (component.inheritedFrom.length) {
      lines.push(
        `${component.inheritedFrom.map((type) => `\`${type}\``).join(', ')} — everything not listed above is spread onto the underlying \`<${element}>\`, including \`id\`, \`style\`, \`onClick\`, \`aria-*\`, and \`data-*\` attributes.`,
        '',
      );
    } else {
      lines.push(
        `Everything not listed above is spread onto the underlying \`<${element}>\` element.`,
        '',
      );
    }
  }

  if (component.examples.length) {
    lines.push(heading(base, 'Usage'), '');
    component.examples.forEach((example, index) => {
      if (component.examples.length > 1) lines.push(`*Example ${index + 1}*`, '');
      lines.push(codeBlock(normaliseProse(example)), '');
    });
  }

  if (component.composition.length) {
    lines.push(heading(base, 'Composition'), '');
    component.composition.forEach((note) => lines.push(normaliseProse(note), ''));
  }

  if (component.accessibility.length) {
    lines.push(heading(base, 'Accessibility'), '');
    component.accessibility.forEach((note) => lines.push(normaliseProse(note), ''));
  }

  if (component.notes.length) {
    lines.push(heading(base, 'Notes'), '');
    component.notes.forEach((note) => lines.push(normaliseProse(note), ''));
  }

  if (component.types.length) {
    lines.push(heading(base, 'Types'), '');
    component.types.forEach((type) => lines.push(typeBlock(type, base + 1), ''));
  }

  return lines.join('\n');
}

function renderMigrationsForComponent(entry, breakingChanges) {
  const related = breakingChanges.filter((change) => (change.affects ?? []).includes(entry.slug));
  if (!related.length) return '';
  const lines = [heading(2, 'Migration notes'), ''];
  for (const change of related) {
    lines.push(`- [${change.title}](./migrations.md#${slugify(change.title)}) — shipped in v${change.version}.`);
    for (const note of change.notes ?? []) lines.push(`  - ${normaliseProse(note)}`);
  }
  return lines.join('\n');
}

export function renderComponentPage(entry, components, ctx) {
  const single = components.length === 1;
  const lines = [GENERATED_NOTICE, '', heading(1, entry.title), ''];
  lines.push(
    `*${ctx.group.title}${entry.usedFor ? ` · ${entry.usedFor}` : ''}*`,
    '',
    `**Page status:** ${entry.status}${entry.issue ? ` · Tracks ${entry.issue}` : ''}`,
    '',
  );

  if (!single) {
    lines.push(heading(2, 'Exports'), '');
    for (const component of components) {
      const summary = firstSentence(component.description) || 'Documented below.';
      lines.push(`- [\`${component.name}\`](#${componentAnchor(component)}) — ${summary}`);
    }
    lines.push('');
  }

  for (const component of components) {
    lines.push(renderComponentSection(component, { ...ctx, singleExport: single }), '');
  }

  const migrationSection = renderMigrationsForComponent(entry, ctx.breakingChanges);
  if (migrationSection) lines.push(migrationSection, '');

  if (entry.related?.length) {
    lines.push(heading(2, 'Related'), '');
    for (const relatedSlug of entry.related) {
      const related = ctx.registry.find((item) => item.slug === relatedSlug);
      if (related) lines.push(`- [${related.title}](./${related.slug}.md)`);
    }
    lines.push('');
  }

  lines.push(
    '---',
    '',
    `[← All components](./README.md) · [Migration guide](./migrations.md) · Documented at v${ctx.version}`,
  );
  return lines.join('\n') + '\n';
}

// ─────────────────────────────────────────────────────────────────────────────
// Index page
// ─────────────────────────────────────────────────────────────────────────────

export function renderIndexPage(pages, ctx) {
  const lines = [GENERATED_NOTICE, '', heading(1, ctx.library.title), '', ctx.library.tagline, ''];
  lines.push(
    `**Library version:** ${ctx.version} · **Components:** ${ctx.componentCount} · **Exports:** ${ctx.exportCount}`,
    '',
    'Props, types, and defaults on every page below are extracted from the TypeScript source and its JSDoc by `npm run docs:build`. Nothing here is written twice.',
    '',
  );

  lines.push(heading(2, 'Components by group'), '');
  for (const group of ctx.groups) {
    const groupPages = pages.filter((page) => page.group === group.id);
    if (!groupPages.length) continue;
    lines.push(heading(3, group.title), '', group.blurb, '');
    lines.push('| Component | Exports | Status | Used for |', '| --- | --- | --- | --- |');
    for (const page of groupPages) {
      lines.push(
        `| ${mdCell(`[${page.title}](./${page.slug}.md)`)} | ${mdCell(mdCode(page.exports.join(', ')))} | ${page.status} | ${mdCell(page.usedFor ?? '—')} |`,
      );
    }
    lines.push('');
  }

  lines.push(heading(2, 'Composition patterns'), '');
  lines.push('Library pieces are designed to be combined. These patterns are used across the app:', '');
  for (const pattern of ctx.patterns) {
    lines.push(heading(3, pattern.title), '', pattern.summary, '', codeBlock(pattern.code), '');
  }

  lines.push(heading(2, 'Accessibility baseline'), '');
  lines.push('Every component below is documented with its own accessibility notes. The shared rules are:', '');
  for (const principle of ctx.a11yPrinciples) {
    lines.push(`- **${principle.title}** — ${principle.detail}`);
  }
  lines.push('');

  lines.push(heading(2, 'Versioning'), '');
  lines.push(
    `These docs are versioned with the web app: this page describes v${ctx.version}, matching the \`version\` field in \`web/package.json\`.`,
    '',
    '`npm run docs:release` freezes the current output under `versions/<version>.json` and publishes a versioned snapshot of the docs site, so older releases stay browsable. Breaking changes are recorded per release in the [migration guide](./migrations.md).',
    '',
  );

  lines.push(heading(2, 'Maintaining these docs'), '');
  lines.push(
    'Add the component to `scripts/docs/registry.mjs`, write JSDoc on the component and its props interface, then run `npm run docs:build`. The generated files live in [`web/docs/components`](' +
      ctx.library.docsUrl +
      ').',
    '',
    '| Want to document | Write |',
    '| --- | --- |',
    '| Prop description | JSDoc above the prop in the props interface |',
    '| Default value | inline default in destructuring, or `@default` |',
    '| Usage example | `@example` above the component |',
    '| Accessibility notes | `@accessibility` above the component |',
    '| Composition guidance | `@composition` above the component |',
    '| Deprecation and replacement | `@deprecated` above the component |',
    '| Breaking change | `scripts/docs/breaking-changes.json` |',
    '',
    '`npm run docs:check` fails when any generated file is stale, so these docs cannot silently drift from the code.',
    '',
  );

  lines.push('---', '', '[Migration guide](./migrations.md) · [Versions](./versions.md)');
  return lines.join('\n') + '\n';
}

// ─────────────────────────────────────────────────────────────────────────────
// Migration guide
// ─────────────────────────────────────────────────────────────────────────────

export function renderMigrationsPage(ctx) {
  const lines = [GENERATED_NOTICE, '', heading(1, 'Migration guide'), '', ctx.migrationIntro, ''];

  lines.push(heading(2, 'Releases'), '');
  lines.push('| Version | Date | Summary |', '| --- | --- | --- |');
  for (const release of ctx.releases) {
    lines.push(
      `| ${mdCell(`[v${release.version}](#${slugify(`release ${release.version}`)})`)} | ${release.date} | ${mdCell(release.summary)} |`,
    );
  }
  lines.push('');

  for (const release of ctx.releases) {
    lines.push(heading(2, `v${release.version}`), '');
    lines.push(`<a id="${slugify(`release ${release.version}`)}"></a>`, '');
    lines.push(release.summary, '');
    for (const change of release.changes) {
      lines.push(heading(3, change.title), '');
      lines.push(
        `**Severity:** ${change.severity}${change.component ? ` · **Affected component:** [${change.component}](./${change.component}.md)` : ''}`,
        '',
      );
      lines.push(change.summary, '');
      if (change.from) {
        lines.push(heading(4, change.from.label ?? 'Before'), '');
        lines.push(beforeAfterTable(ctx.byName.get(change.from.component), 'Removed or changed in the new API'), '');
      }
      if (change.to) {
        lines.push(heading(4, change.to.label ?? 'After'), '');
        lines.push(beforeAfterTable(ctx.byName.get(change.to.component), 'Current API'), '');
      }
      if (change.mapping?.length) {
        lines.push(heading(4, 'Call-site migration'), '');
        for (const item of change.mapping) {
          lines.push('Before:', '', codeBlock(item.from), '', 'After:', '', codeBlock(item.to), '');
        }
      }
      if (change.notes?.length) {
        lines.push(heading(4, 'Notes'), '');
        for (const note of change.notes) lines.push(`- ${normaliseProse(note)}`);
        lines.push('');
      }
      if (change.codemod) {
        lines.push(heading(4, 'Codemod'), '', codeBlock(change.codemod, 'bash'), '');
      }
    }
  }

  lines.push(heading(2, 'Handling a deprecation'), '');
  lines.push(
    '`@deprecated` in JSDoc automatically raises a banner on the component page and links the replacement. Use it together with an entry in `scripts/docs/breaking-changes.json` so consumers get a mechanical migration, not just a warning.',
    '',
    '---',
    '',
    '[← All components](./README.md) · [Versions](./versions.md)',
  );
  return lines.join('\n') + '\n';
}

function beforeAfterTable(component, caption) {
  if (!component) return '_Not resolvable in the current registry._';
  const rows = component.props.map((prop) => ({
    ...prop,
    name: prop.optional ? prop.name : `${prop.name} (required)`,
  }));
  if (component.restMember) rows.push(component.restMember);
  const table = rows.length
    ? propsTable(rows)
    : `\`${component.name}\` declares no props beyond the native element attributes.`;
  return [`*${caption} — \`${component.name}\` from \`${component.file}\`*`, '', table].join('\n');
}
